"""Package an unmodified pinned HRA GLB; no geometry processing or runtime network."""
import base64, hashlib, json, pathlib, struct, urllib.request
COMMIT = 'f1a3a63f110e27ff0736047d52d04dba5d3087f9'
URL = f'https://raw.githubusercontent.com/hubmapconsortium/ccf-3d-reference-object-library/{COMMIT}/VH_Female/v1.2/VH_F_Lung.glb'
EXPECTED = 'a6a81718f4d0974bcbab47c6dc38efc941ad5c7f5f256bf7ff112c710a7fd932'
b = urllib.request.urlopen(URL).read()
assert hashlib.sha256(b).hexdigest() == EXPECTED
j = json.loads(b[20:20+struct.unpack_from('<I',b,12)[0]])
root = pathlib.Path(__file__).resolve().parents[2] / 'respiratory-study/assets'
(root/'model-data.js').write_text('/* HRA reference anatomy, CC BY 4.0; see ATTRIBUTION.md. */\nwindow.RespiratoryModelData="'+base64.b64encode(b).decode()+'";\n')
manifest = dict(id='hra-lung',sourceURL=URL,sourceCommit=COMMIT,creator='Kristen Browne and Heidi Schlehlein / HuBMAP Human Reference Atlas; NLM Visible Human',license='CC BY 4.0',licenseURL='https://creativecommons.org/licenses/by/4.0/',licenseSnapshotDate='2026-10-17',originalSha256=EXPECTED,transformedSha256=EXPECTED,bytes=len(b),packagedBytes=(root/'model-data.js').stat().st_size,meshes=len(j['meshes']),triangles=sum(j['accessors'][p['indices']]['count']//3 for m in j['meshes'] for p in m['primitives']),animations=len(j.get('animations',[])),units='glTF meters by convention; source physical scale not independently validated',coordinates='glTF right-handed; +Y superior and +X patient left supported by named source branch bounds; anterior Z requires educator review',transform='One root scale to fit bounds height to 3 scene units, one shared root translation; no independent mesh fitting. Source hierarchy and relative transforms preserved.',processing='Python 3 standard library; exact GLB bytes base64 transport only',registration='Standalone respiratory atlas only. Not aligned or combined with male BodyParts3D thorax or isolated heart.',limits=['No nasal cavity, pharynx, bronchioles, alveolar microstructure, pleura or diaphragm meshes selected. These use explicit schematics.','Cartilage is not a complete functional larynx.','Named source branches are reference mapping, not educator-validated anatomical continuity.','378963 triangles exceed 250000 target; optional load, static reference, no physiological deformation.','No actual iPad performance certification.'],nodes=[dict(name=n.get('name'),mesh=n.get('mesh'),children=n.get('children',[]),matrix=n.get('matrix'),translation=n.get('translation'),rotation=n.get('rotation'),scale=n.get('scale')) for n in j['nodes']],meshInventory=[dict(name=m['name'],triangles=sum(j['accessors'][p['indices']]['count']//3 for p in m['primitives']))for m in j['meshes']])
(root/'model-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(json.dumps({k:manifest[k]for k in ['bytes','packagedBytes','meshes','triangles','originalSha256']}))
